def calculate_current_streak(all_dates, streak):
	if not all_dates:
		return 0
	last_date = all_dates[-1]
	today = getdate()
	ref_day = today
	while ref_day.weekday() in (5, 6):
		ref_day -= timedelta(days=1)
	if last_date == ref_day or last_date == ref_day - timedelta(days=1):
		return streak

